import math

# Reversing controller for narrow alley.
# Steers towards side of hitch swing while reversing.
MAX_STEER = 45  # degrees (wheel limit)
REVERSE_SPEED = -0.6  # m/s (moderate reverse speed)
HITCH_THRESHOLD = 4  # degrees; begin correction when hitch exceeds this

def clamp(val, lo, hi):
    return max(lo, min(hi, val))

def control(obs):
    hitch = obs.get('hitch_deg', 0.0)
    if hitch > HITCH_THRESHOLD:
        steer = clamp(MAX_STEER, -MAX_STEER, MAX_STEER)   # turn left (+) to reduce positive hitch
    elif hitch < -HITCH_THRESHOLD:
        steer = clamp(-MAX_STEER, -MAX_STEER, MAX_STEER)  # turn right (-) to reduce negative hitch
    else:
        steer = 0.0
    speed = REVERSE_SPEED
    look = 0.0  # keep looking straight ahead
    return (steer, speed, look)

